import { useControl } from '@conform-to/react/future';

export function Rating({ name }: { name: string }) {
  const control = useControl({ name, initialValue: '0' });

  return (
    <div>
      <input {...control.register()} type="hidden" />
      {[1, 2, 3, 4, 5].map((rating) => (
        <button
          key={rating}
          type="button"
          aria-pressed={control.value === String(rating)}
          onClick={() => control.change(String(rating))}
        >
          {rating}
        </button>
      ))}
    </div>
  );
}

